import{_ as a,a as i,c as r,ac as t}from"./chunks/framework.BSuaGltH.js";const u=JSON.parse('{"title":"Redis 知识复盘 · 分布式锁与并发写至继续学习","description":"按数据、内存、持久化、复制分片、事务、锁与缓存异常建立完整学习路径。","frontmatter":{"title":"Redis 知识复盘 · 分布式锁与并发写至继续学习","description":"按数据、内存、持久化、复制分片、事务、锁与缓存异常建立完整学习路径。","splitFrom":"middleware/redis/pro/interview/redis-面试.md","showdocs":{"topics":[{"id":"redis","title":"Redis","link":"/topics/redis/"}],"kind":"数据与原子性","scope":"general","audience":"general","group":"数据库与存储","seriesTitle":"Redis 知识复盘","summary":"按数据、内存、持久化、复制分片、事务、锁与缓存异常建立完整学习路径。","status":"active","related":[{"title":"Redis 操作与命令","link":"/middleware/redis/plus/ecosystem/redis-general-general","kind":"数据与原子性","scope":"general","audience":"general"},{"title":"Redis 数据类型命令速查","link":"/middleware/redis/plus/subjects/redis-data-cmd","kind":"数据与原子性","scope":"general","audience":"general"},{"title":"Redis 完整实践：Lua 原子限额与可重试 CLI","link":"/middleware/redis/plus/practice/quota","kind":"完整实践","scope":"general","audience":"general"},{"title":"Redis 游戏与通用后端场景","link":"/middleware/redis/pro/practice/game-scenarios","kind":"完整实践","scope":"general","audience":"general"},{"title":"Redis 持久化：RDB、AOF 与独立恢复","link":"/middleware/redis/persistence-and-recovery","kind":"数据与原子性","scope":"general","audience":"general"}],"prev":{"text":"Redis 知识复盘 · 数据结构与使用边界至事务与条件更新","link":"/middleware/redis/pro/interview/redis-面试-part-01"},"next":false},"layout":"ReadingPage","sidebar":false,"aside":false,"prev":{"text":"Redis 知识复盘 · 数据结构与使用边界至事务与条件更新","link":"/middleware/redis/pro/interview/redis-面试-part-01"},"next":false},"headers":[],"relativePath":"middleware/redis/pro/interview/redis-面试-part-02.md","filePath":"middleware/redis/pro/interview/redis-面试-part-02.md"}'),d={name:"middleware/redis/pro/interview/redis-面试-part-02.md"};function l(s,e,n,o,c,p){return i(),r("div",null,[...e[0]||(e[0]=[t('<h1 id="redis-知识复盘-·-分布式锁与并发写至继续学习" tabindex="-1">Redis 知识复盘 · 分布式锁与并发写至继续学习 <a class="header-anchor" href="#redis-知识复盘-·-分布式锁与并发写至继续学习" aria-label="Permalink to &quot;Redis 知识复盘 · 分布式锁与并发写至继续学习&quot;">​</a></h1><p><a href="/middleware/redis/pro/interview/redis-面试">返回分篇目录</a></p><p>先按业务选择数据结构，再理解内存、持久化与复制，最后处理事务、锁和缓存异常。每节集中回答一类问题，避免把同一概念拆成多组问答。</p><h2 id="locking" tabindex="-1">分布式锁与并发写 <a class="header-anchor" href="#locking" aria-label="Permalink to &quot;分布式锁与并发写 {#locking}&quot;">​</a></h2><p>先判断是否真的需要跨请求锁：计数优先用 <code>INCR</code> 等原子命令，条件更新可用 <code>WATCH</code> 或脚本。需要锁时，获取与过期时间应在同一条 <code>SET key token NX PX ...</code> 中设置。</p><ul><li>token 应能标识本次持有者；释放时原子比较 token 再删除，不能直接 <code>DEL</code> 其他持有者的锁。</li><li>业务可能执行超过租约；要考虑续租、暂停、超时与进程崩溃。锁过期不代表旧持有者已停止访问外部资源。</li><li>保护数据库或其他系统时，还要考虑 fencing token、幂等或版本校验等资源端保护。</li><li>Redlock 有运行与时序假设，不能当作不加条件的“官方保证安全”。选型应以业务容错要求为依据。</li></ul><p>具体读写流程与释放脚本见 <a href="/middleware/redis/plus/practice/cache-and-lock">缓存与锁实践</a>。</p><h2 id="cache-design" tabindex="-1">缓存读写与异常处理 <a class="header-anchor" href="#cache-design" aria-label="Permalink to &quot;缓存读写与异常处理 {#cache-design}&quot;">​</a></h2><h3 id="先定义数据一致性要求" tabindex="-1">先定义数据一致性要求 <a class="header-anchor" href="#先定义数据一致性要求" aria-label="Permalink to &quot;先定义数据一致性要求 {#先定义数据一致性要求}&quot;">​</a></h3><p>常见旁路缓存流程是读缓存，未命中再读数据库并回填；写入时先更新数据库，再删除相关缓存。数据库成功、删缓存失败时需重试或补偿；并发回填也可能产生短暂旧值，TTL 只是限制旧值存活时间，不是严格一致性证明。</p><p>必须强一致的判断应回到权威数据源或采用适合该业务的协调方案，不能仅靠两个系统连续写入保证原子性。</p><h3 id="穿透、击穿与雪崩不要混淆" tabindex="-1">穿透、击穿与雪崩不要混淆 <a class="header-anchor" href="#穿透、击穿与雪崩不要混淆" aria-label="Permalink to &quot;穿透、击穿与雪崩不要混淆 {#穿透、击穿与雪崩不要混淆}&quot;">​</a></h3><table tabindex="0"><thead><tr><th>问题</th><th>典型触发</th><th>应对</th></tr></thead><tbody><tr><td>穿透</td><td>查询不存在的数据</td><td>输入校验、短期空值缓存、布隆过滤器</td></tr><tr><td>击穿</td><td>一个热点键失效，大量请求同时回源</td><td>同键请求合并、受控重建、允许时逻辑过期</td></tr><tr><td>雪崩</td><td>大片键同时失效或缓存整体故障</td><td>TTL 分散、限流、预热、熔断与有边界的降级</td></tr></tbody></table><p>布隆过滤器判断“不存在”可以排除数据；判断“可能存在”仍需继续查，不能反向理解。通常不直接支持删除，更新数据时也要维护过滤器。</p><p>预热只加载有预期访问的数据，逐批限制并发；热点重建失败要有超时和兜底，不能无限排队。缓存故障时也不能让所有请求无限回源；哪些场景允许旧值或默认值，应由业务定义，结算等关键行为不能用静默成功替代。</p><h2 id="practice" tabindex="-1">队列、客户端与复习检查 <a class="header-anchor" href="#practice" aria-label="Permalink to &quot;队列、客户端与复习检查 {#practice}&quot;">​</a></h2><h3 id="消息与延迟任务" tabindex="-1">消息与延迟任务 <a class="header-anchor" href="#消息与延迟任务" aria-label="Permalink to &quot;消息与延迟任务 {#消息与延迟任务}&quot;">​</a></h3><ul><li>List 可配合阻塞弹出减少空轮询，但弹出后消费者崩溃时如何恢复需要单独设计。</li><li>Pub/Sub 面向在线订阅者，不提供离线积压与消费确认。</li><li>Sorted Set 可把到期时间作为 score；多个消费者竞争时，取出和移除需要原子性，并考虑执行失败重试与重复投递。</li><li>需要持久消息、消费组或重放时比较 Stream 与专用消息系统，不只比较命令是否能收发。</li></ul><h3 id="客户端选择与复习验收" tabindex="-1">客户端选择与复习验收 <a class="header-anchor" href="#客户端选择与复习验收" aria-label="Permalink to &quot;客户端选择与复习验收 {#客户端选择与复习验收}&quot;">​</a></h3><p>Jedis、Lettuce、Redisson 的抽象层次与功能不同，按维护版本、连接模型、Cluster 支持及实际 API 选择，不沿用过时的“官方只推荐某一个”或“某客户端不支持字符串”等绝对结论。</p><p>用自己的场景回答以下问题，而不是背诵固定机器数或 QPS：</p><ol><li>哪些键可以过期或淘汰？内存不足时写失败如何处理？</li><li>主库故障后允许丢多少更新？备份最近一次恢复是否成功？</li><li>一次事务内部分命令运行失败，会留下什么状态？</li><li>同一热点键失效时，最大有多少请求能回源？</li><li>分片后有关联的多键操作如何保持同槽或改造？</li></ol><h2 id="继续学习" tabindex="-1">继续学习 <a class="header-anchor" href="#继续学习" aria-label="Permalink to &quot;继续学习 {#继续学习}&quot;">​</a></h2><ul><li><a href="/middleware/redis/plus/subjects/redis-config">Redis 配置与历史样例</a></li><li><a href="https://redis.io/docs/latest/develop/using-commands/transactions/" target="_blank" rel="noopener noreferrer">Redis 事务语义</a></li><li><a href="https://redis.io/docs/latest/operate/oss_and_stack/management/persistence/" target="_blank" rel="noopener noreferrer">Redis 持久化</a></li><li><a href="https://redis.io/docs/latest/operate/oss_and_stack/reference/cluster-spec/" target="_blank" rel="noopener noreferrer">Cluster 协议与限制</a></li></ul>',24)])])}const m=a(d,[["render",l]]);export{u as __pageData,m as default};
